-- Import in phpMyAdmin. All table names are singular.
CREATE DATABASE IF NOT EXISTS little_blossoms CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE little_blossoms;
CREATE TABLE IF NOT EXISTS user (id INT AUTO_INCREMENT PRIMARY KEY, first_name VARCHAR(80) NOT NULL, last_name VARCHAR(80) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, phone VARCHAR(25) NOT NULL, password_hash VARCHAR(255) NOT NULL, role ENUM('parent','admin') NOT NULL DEFAULT 'parent', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS fee (id INT AUTO_INCREMENT PRIMARY KEY, category ENUM('babies','wobblers','toddlers','preschool') NOT NULL, care_type ENUM('Half day','Full day') NOT NULL, days_per_week TINYINT NOT NULL, weekly_price DECIMAL(8,2) NOT NULL, UNIQUE KEY uq_fee(category,care_type,days_per_week));
CREATE TABLE IF NOT EXISTS child (id INT AUTO_INCREMENT PRIMARY KEY,parent_id INT NOT NULL,fee_id INT NOT NULL,name VARCHAR(120) NOT NULL,date_of_birth DATE NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(parent_id) REFERENCES user(id),FOREIGN KEY(fee_id) REFERENCES fee(id));
CREATE TABLE IF NOT EXISTS day (id INT AUTO_INCREMENT PRIMARY KEY,child_id INT NOT NULL,day_date DATE NOT NULL,temperature DECIMAL(3,1) NULL,breakfast VARCHAR(500) NOT NULL DEFAULT '',lunch VARCHAR(500) NOT NULL DEFAULT '',activities TEXT NOT NULL,UNIQUE KEY uq_child_day(child_id,day_date),FOREIGN KEY(child_id) REFERENCES child(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS feature (id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(150) NOT NULL,detail TEXT NOT NULL,image_path VARCHAR(255) NOT NULL,link_path VARCHAR(255) NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS service (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,summary TEXT NOT NULL,image_path VARCHAR(255) NOT NULL,link_path VARCHAR(255) NOT NULL);
CREATE TABLE IF NOT EXISTS testimonial (id INT AUTO_INCREMENT PRIMARY KEY,parent_id INT NOT NULL,service_id INT NOT NULL,comment TEXT NOT NULL,approved TINYINT(1) NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(parent_id) REFERENCES user(id),FOREIGN KEY(service_id) REFERENCES service(id));
CREATE TABLE IF NOT EXISTS contact_us (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL,phone VARCHAR(25) NOT NULL,message TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS page (id INT AUTO_INCREMENT PRIMARY KEY,label VARCHAR(80) NOT NULL,path VARCHAR(190) NOT NULL UNIQUE,access_level ENUM('public','parent','admin') NOT NULL,show_nav TINYINT(1) NOT NULL DEFAULT 1,sort_order INT NOT NULL DEFAULT 0);
